// Observe native history/selection transitions rather than emulate private STORE.
// Only transient common state is projected; callers still verify business data,
// ownership, geometry and the full declared operation postimage.
using System;using System.Collections;using System.Collections.Generic;using System.Globalization;
namespace McgsInternalBridge {
 internal sealed class NativeHistoryStoreProjection {
  internal const string ProfileSha="b22e679312aaa5d506c474caf4bbb5209eb6be938305961e02eaa228b70ef5f9";
  readonly NativeEngine engine;readonly IntPtr doc;readonly int thread;
  readonly Dictionary<uint,uint> original=new Dictionary<uint,uint>(),expected=new Dictionary<uint,uint>();
  readonly List<IntPtr> top=new List<IntPtr>();internal readonly Dictionary<string,object> Before;bool stored,selectionPrepared,embeddedCommand;
  static Dictionary<string,object> M(object value){return NativePageControlPreparation.Map(value);}static int N(object value){return NativeEngine.Number(value);}
  internal static NativeHistoryStoreProjection Prepare(NativeEngine engine,IntPtr doc){return new NativeHistoryStoreProjection(engine,doc);}
  NativeHistoryStoreProjection(NativeEngine e,IntPtr document){engine=e;doc=document;thread=NativeMemory.GetCurrentThreadId();Before=Capture();foreach(object value in(IEnumerable)Before["top_controls"]){var row=M(value);uint address=unchecked((uint)N(row["complete"])),raw=Convert.ToUInt32(row["raw_DWORD60"]);top.Add(new IntPtr(unchecked((int)address)));original.Add(address,raw);expected.Add(address,raw);}}
  void Guard(){NativeMemory.Require(IntPtr.Size==4&&NativeMemory.GetCurrentThreadId()==thread&&thread==EngineEntry.ExpectedUiThreadId,"History observation requires its original UI thread.");NativeMemory.Require(NativeMemory.Ptr(doc,0)==engine.Address(0xDC4D94),"History observation document identity differs.");}
  Dictionary<string,object> Capture(){Guard();var controls=NativeDynamicCollections.ReadDrawList(NativeMemory.Add(doc,NativeLayout.Offset("document.controls")),doc,engine.Address(0xD3FD70));var rows=new List<object>();foreach(IntPtr full in controls){uint raw=unchecked((uint)NativeMemory.I32(full,NativeLayout.Offset("control.raw_state")));rows.Add(new Dictionary<string,object>{{"complete",NativeMemory.Hex(full)},{"raw_DWORD60",raw},{"expected_after_original_store_uint32",raw}});}return new Dictionary<string,object>{{"abi_profile_sha256",ProfileSha},{"document",NativeMemory.Hex(doc)},{"top_controls",rows},{"mode","observe original notification"},{"nested_controls_projected",false},{"managed_raw_state_writes",false}};}
  internal void ValidateBefore(){NativeMemory.Require(!stored,"History observation was already consumed.");NativePageControlPreparation.Same(Before,Capture(),"Control history preimage changed.");}
  internal void OriginalStoreReturned(){Guard();var now=Capture();var rows=(IList)now["top_controls"];NativeMemory.Require(rows.Count==top.Count,"Original history changed top-level control count.");for(int i=0;i<rows.Count;i++){var row=M(rows[i]);NativeMemory.Require(Convert.ToString(row["complete"])==NativeMemory.Hex(top[i]),"Original history changed top-level ownership/order.");expected[NativeMemory.U(top[i])]=Convert.ToUInt32(row["raw_DWORD60"]);}stored=true;}
  // The caller validates the original selection's exact identities/order.
  internal void OriginalSelectionReturned(IEnumerable<IntPtr> targets){Guard();NativeMemory.Require(!stored&&!selectionPrepared,"Native selection/history already consumed.");var selected=new HashSet<uint>();foreach(IntPtr full in targets)NativeMemory.Require(original.ContainsKey(NativeMemory.U(full))&&selected.Add(NativeMemory.U(full)),"Original command selection repeats or is outside the original owner list.");NativeMemory.Require(selected.Count>0,"Original command selection is empty.");selectionPrepared=true;}
  internal void OriginalCommandWithEmbeddedStoreReturned(){Guard();NativeMemory.Require(selectionPrepared&&!stored,"Embedded history needs the validated original selection.");int id=NativeMemory.I32(doc,NativeLayout.Offset("document.archive_id"));foreach(var row in NativeUsableEditPermit.CurrentDrawControls(engine,doc,id)){object address;if(row.TryGetValue("complete",out address)){uint full=unchecked((uint)N(address));object raw;if(original.ContainsKey(full)&&(row.TryGetValue("raw_DWORD60",out raw)||row.TryGetValue("field_60_raw_uint32",out raw)))expected[full]=Convert.ToUInt32(raw);}}stored=true;embeddedCommand=true;}
  internal bool OriginalBeforeModifyReturned{get{return stored;}}
  internal uint ExpectedRaw60(IntPtr complete,uint beforeValue){uint old;NativeMemory.Require(original.TryGetValue(NativeMemory.U(complete),out old)&&old==beforeValue,"History state is not a captured original control/value.");return expected[NativeMemory.U(complete)];}
  internal uint ExpectedOrUnchangedRaw60(IntPtr complete,uint beforeValue){uint old;if(!original.TryGetValue(NativeMemory.U(complete),out old))return beforeValue;NativeMemory.Require(old==beforeValue,"Original common control state differs.");return expected[NativeMemory.U(complete)];}
  internal object ExpectedSnapshot(object value){object copy=NativeDynamicCollections.CopyValue(value,false);Project(copy);return copy;}
  internal object AfterStoreSnapshot(object value){return stored?ExpectedSnapshot(value):NativeDynamicCollections.CopyValue(value,false);}
  internal void ProjectExpectedSnapshotInPlace(Dictionary<string,object> value){NativeMemory.Require(stored,"History projection needs a returned original call.");Project(value);}
  void Project(object value){foreach(var row in NativeDynamicCollections.DictionaryValues(value)){object address;if(!row.TryGetValue("complete",out address)||!(address is string))continue;uint full=unchecked((uint)N(address)),old;if(!original.TryGetValue(full,out old))continue;foreach(string key in new[]{"raw_DWORD60","raw60","field_60_raw_uint32"})if(row.ContainsKey(key)){NativeMemory.Require(Convert.ToUInt32(row[key],CultureInfo.InvariantCulture)==old,"Expected image has another original state.");row[key]=expected[full];}}}
  internal Dictionary<string,object> Report(){var states=new List<object>();foreach(var pair in original)states.Add(new Dictionary<string,object>{{"complete",NativeMemory.Hex(new IntPtr(unchecked((int)pair.Key)))},{"before",pair.Value},{"after",expected[pair.Key]}});return new Dictionary<string,object>{{"abi_profile_sha256",ProfileSha},{"before",Before},{"observed_transient_state_changes",states},{"original_before_modify_returned",stored&&!embeddedCommand},{"original_command_with_embedded_store_returned",embeddedCommand},{"original_selection_verified_by_caller",selectionPrepared},{"private_store_implementation_emulated",false},{"managed_raw_state_writes",false},{"nested_controls_projected",false}};}
 }
}
